import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import Footer from '../components/Footer';
import axios from 'axios';

const API = `http://${window.location.hostname}:5000/api`;
const BACKEND = `http://${window.location.hostname}:5000`;

function getCategoryTag(sectionKey) {
  if (!sectionKey) return null;
  if (sectionKey.includes('문화면')) return { label: '문화', color: 'bg-pink-600' };
  if (sectionKey.includes('칼럼')) return { label: '교수칼럼', color: 'bg-purple-600' };
  if (sectionKey.includes('기자한마디')) return { label: '기자한마디', color: 'bg-indigo-600' };
  if (sectionKey.includes('조명탑')) return { label: '오피니언', color: 'bg-orange-600' };
  if (sectionKey.includes('기획')) return { label: '기획', color: 'bg-teal-600' };
  if (sectionKey.includes('지역사회')) return { label: '지역사회', color: 'bg-emerald-600' };
  if (sectionKey.includes('1면')) return { label: '학생자치', color: 'bg-blue-600' };
  if (sectionKey.includes('2면')) return { label: '학술', color: 'bg-green-600' };
  return null;
}

function stripHtmlToText(html) {
  if (!html) return '';
  const tmp = document.createElement('DIV');
  tmp.innerHTML = html;
  return tmp.textContent || tmp.innerText || '';
}

function MainPage() {
  const [activeTab, setActiveTab] = useState('전체뉴스보기');
  const { isLoggedIn, user } = useAuth();
  const [approvedData, setApprovedData] = useState({ articles: [], tabs: [], tabPageMap: [], newspaper: null });
  const scrollRef = useRef(null);

  useEffect(() => {
    axios.get(`${API}/newspapers/approved/articles`)
      .then(res => {
        setApprovedData(res.data);
        if (res.data.tabs && res.data.tabs.length > 0) {
          setActiveTab('전체뉴스보기');
        }
      })
      .catch(() => {});
  }, []);

  const tabs = approvedData.tabs && approvedData.tabs.length > 0 ? approvedData.tabs : [];

  const filteredArticles = (() => {
    if (!approvedData.articles || approvedData.articles.length === 0) return [];
    const tabIndex = tabs.indexOf(activeTab);
    if (tabIndex <= 0) return approvedData.articles; // 전체뉴스보기 또는 기본
    const pageNum = approvedData.tabPageMap[tabIndex];
    return approvedData.articles.filter(a => a.page_number === pageNum);
  })();

  const scrollLeft = () => { if (scrollRef.current) scrollRef.current.scrollBy({ left: -320, behavior: 'smooth' }); };
  const scrollRight = () => { if (scrollRef.current) scrollRef.current.scrollBy({ left: 320, behavior: 'smooth' }); };

  return (
    <>
      <main className="max-w-7xl mx-auto px-6 py-8">

        {/* 로그인 환영 배너 */}
        {isLoggedIn && (
          <div className="mb-6 bg-gradient-to-r from-[#004b93] to-[#0072bc] rounded-2xl p-5 text-white flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center font-bold">
                {user.name?.charAt(0)}
              </div>
              <div>
                <p className="font-bold">{user.nickname || user.name}님, 오늘도 대진대 소식을 확인하세요!</p>
                <p className="text-sm text-blue-200">
                  {user.role === 'admin' && '편집장/관리자로 로그인 중'}
                  {user.role === 'reporter' && '기자로 로그인 중 — 기사를 작성할 수 있습니다'}
                  {user.role === 'reader' && '독자로 로그인 중 — 댓글과 반응을 남겨보세요'}
                </p>
              </div>
            </div>
          </div>
        )}

        {/* 섹션 1: 히어로 슬라이드 */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-12">
          <div className="lg:col-span-2 relative h-[450px] rounded-3xl overflow-hidden shadow-2xl group">
            <img
              src="https://images.unsplash.com/photo-1541339907198-e08756ebafe3?auto=format&fit=crop&w=1200"
              alt="Campus News"
              className="w-full h-full object-cover group-hover:scale-105 transition duration-700"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent flex flex-col justify-end p-8 text-white">
              <span className="bg-red-500 text-xs font-bold px-3 py-1 rounded-full w-fit mb-4">HOT ISSUE</span>
              <h2 className="text-3xl md:text-4xl font-extrabold mb-2 leading-tight">
                2026학년도 대진대학교 신규 장학제도 개편... 무엇이 달라지나?
              </h2>
              <p className="text-gray-300 mb-6 max-w-xl">
                학생 복지 위원회와 대학 본부의 긴밀한 협의 끝에 탄생한 새로운 장학금 가이드라인을 심층 보도합니다.
              </p>
              <div className="flex items-center space-x-4">
                <span className="text-sm"><i className="far fa-calendar mr-2"></i>2026.03.15</span>
                <span className="text-sm"><i className="far fa-comment-dots mr-2"></i>124</span>
              </div>
            </div>
          </div>

          {/* 우측 실시간 핫 댓글 */}
          <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100 flex flex-col">
            <h3 className="text-lg font-extrabold mb-4 flex items-center">
              <span className="w-2 h-6 bg-[#004b93] mr-3 rounded-full"></span>
              지금 뜨거운 학보 댓글
            </h3>
            <div className="space-y-4 flex-1 overflow-y-auto scroll-hide">
              <div className="p-4 bg-gray-50 rounded-2xl hover:bg-blue-50 cursor-pointer transition">
                <p className="text-sm font-semibold mb-1">"셔틀버스 증차 기사 너무 공감됩니다. 특히 아침 9시 수업..."</p>
                <span className="text-xs text-gray-400">학보 3월호 | 5분 전</span>
              </div>
              <div className="p-4 bg-gray-50 rounded-2xl hover:bg-blue-50 cursor-pointer transition">
                <p className="text-sm font-semibold mb-1">"교수님 오피니언 읽고 생각이 많아졌어요. 인공지능 시대의..."</p>
                <span className="text-xs text-gray-400">학보 3월호 | 20분 전</span>
              </div>
              <div className="p-4 bg-gray-50 rounded-2xl hover:bg-blue-50 cursor-pointer transition">
                <p className="text-sm font-semibold mb-1">"동아리 축제 일정 정리가 아주 깔끔하네요!"</p>
                <span className="text-xs text-gray-400">학보 2월호 | 1시간 전</span>
              </div>
            </div>
            <button className="w-full mt-4 py-3 bg-gray-100 text-gray-600 rounded-2xl font-bold hover:bg-gray-200 transition">
              전체 댓글 보기
            </button>
          </div>
        </div>

        {/* 섹션 2: 큐레이션 탭 */}
        <div className="mb-12">
          <div className="flex space-x-8 mb-8 border-b border-gray-200 overflow-x-auto scroll-hide">
            {tabs.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`pb-4 whitespace-nowrap transition ${
                  activeTab === tab
                    ? 'tab-active'
                    : 'text-gray-400 font-bold hover:text-gray-600'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {/* 카드 1 */}
            <div className="bg-white rounded-3xl overflow-hidden shadow-sm card-hover border border-gray-100">
              <div className="h-48 bg-gray-200 relative">
                <img src="https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=400" alt="Card" className="w-full h-full object-cover" />
                <span className="absolute top-4 left-4 bg-blue-600 text-white text-[10px] font-black px-2 py-1 rounded">학생자치</span>
              </div>
              <div className="p-5">
                <h4 className="font-extrabold text-lg mb-2 leading-snug">제 32대 총학생회 '성실' 출범 인터뷰</h4>
                <div className="flex justify-between items-center text-xs text-gray-400">
                  <span>김대진 기자</span>
                  <span><i className="far fa-heart mr-1"></i> 42</span>
                </div>
              </div>
            </div>

            {/* 카드 2 */}
            <div className="bg-white rounded-3xl overflow-hidden shadow-sm card-hover border border-gray-100">
              <div className="h-48 bg-gray-200 relative">
                <img src="https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=400" alt="Card" className="w-full h-full object-cover" />
                <span className="absolute top-4 left-4 bg-green-600 text-white text-[10px] font-black px-2 py-1 rounded">학술</span>
              </div>
              <div className="p-5">
                <h4 className="font-extrabold text-lg mb-2 leading-snug">인공지능 소프트웨어 학과, 국제 학술대회 은상 수상</h4>
                <div className="flex justify-between items-center text-xs text-gray-400">
                  <span>이정보 기자</span>
                  <span><i className="far fa-heart mr-1"></i> 28</span>
                </div>
              </div>
            </div>

            {/* 카드 3 */}
            <div className="bg-white rounded-3xl overflow-hidden shadow-sm card-hover border border-gray-100">
              <div className="h-48 bg-gray-200 relative">
                <img src="https://images.unsplash.com/photo-1491438590914-bc09fcaaf77a?auto=format&fit=crop&w=400" alt="Card" className="w-full h-full object-cover" />
                <span className="absolute top-4 left-4 bg-purple-600 text-white text-[10px] font-black px-2 py-1 rounded">오피니언</span>
              </div>
              <div className="p-5">
                <h4 className="font-extrabold text-lg mb-2 leading-snug">[교수칼럼] 대학 시절, 당신이 반드시 찾아야 할 세 가지</h4>
                <div className="flex justify-between items-center text-xs text-gray-400">
                  <span>박철학 교수</span>
                  <span><i className="far fa-heart mr-1"></i> 89</span>
                </div>
              </div>
            </div>

            {/* 제보 카드 */}
            <div className="bg-white rounded-3xl overflow-hidden shadow-sm card-hover border border-gray-100 flex flex-col items-center justify-center p-6 text-center bg-blue-50 border-dashed border-2 border-blue-200">
              <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center text-blue-600 mb-4 shadow-sm">
                <i className="fas fa-plus"></i>
              </div>
              <p className="font-bold text-blue-800 mb-1">제보하기</p>
              <p className="text-xs text-blue-600">당신의 소중한 이야기를<br />학보사에 들려주세요.</p>
            </div>
          </div>
        </div>

        {/* 섹션 3: 숏폼 뉴스 */}
        <div className="bg-[#1e293b] rounded-[40px] p-8 md:p-12 text-white">
          <div className="flex justify-between items-end mb-8">
            <div>
              <h3 className="text-2xl font-black mb-2">DJU Quick-News</h3>
              <p className="text-gray-400 text-sm">바쁜 등굣길, 1분 안에 읽는 오늘의 핵심 뉴스</p>
            </div>
            <button className="text-sm font-bold border-b border-gray-500 pb-1">전체보기</button>
          </div>

          <div className="flex space-x-6 overflow-x-auto scroll-hide pb-4">
            {[
              { num: '01', text: '학식 메뉴 앱 연동 시작, 이제 실시간으로 잔여 수량 확인 가능', time: '2시간 전' },
              { num: '02', text: '중앙도서관 24시간 개방 종료 안내 (방학 기간 조정)', time: '5시간 전' },
              { num: '03', text: '대진대 락밴드 동아리 정기 공연, 대강당에서 18시 개최', time: '7시간 전' },
              { num: '04', text: 'IT 서비스 안정화 작업으로 인한 포털 일시 중단 안내', time: '1일 전' },
            ].map((item) => (
              <div key={item.num} className="flex-shrink-0 w-64 bg-slate-800 rounded-3xl p-6 border border-slate-700 hover:border-blue-500 transition cursor-pointer">
                <div className="text-blue-400 text-2xl mb-4 font-black">{item.num}</div>
                <p className="font-bold text-lg mb-4">{item.text}</p>
                <div className="flex items-center text-xs text-gray-500">
                  <i className="far fa-clock mr-1"></i> {item.time}
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <Footer />
    </>
  );
}

export default MainPage;
